from datetime import timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.OptionFilterUniverse = None
        self.SetOptionFilter()

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.pending_entry_time = None
        self.held_option = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_reentry_date = None

    def SetOptionFilter(self):
        option = self.Securities[self.option_symbol]
        option.SetFilter(lambda universe: universe.IncludeWeeklys().Strikes(-100, 100).Expiration(0, 365))

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if previous_fast is None or previous_slow is None:
            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and
            (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        )

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_cross and eligible_time:
            self.pending_entry_time = end_time

    def OnData(self, slice):
        self.HandleUnexpectedSpyEquityPosition()
        self.HandleExpirationProtection()
        self.HandleExitLogic(slice)
        self.HandlePendingEntry(slice)

    def HandlePendingEntry(self, slice):
        if self.pending_entry_time is None or self.pending_entry_time != self.Time:
            return

        self.pending_entry_time = None

        if self.no_reentry_date == self.Time.date():
            self.Debug(f"{self.Time}: Entry skipped; expiration protection is active today.")
            return

        if self.held_option is not None or self.entry_order_id is not None:
            self.Debug(f"{self.Time}: Entry skipped; an option position or entry order already exists.")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped; no SPY option chain in Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug(f"{self.Time}: Entry skipped; no expiration at least seven calendar days away.")
            return

        selected_expiry = expirations[0]
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
        ]

        if not calls:
            self.Debug(f"{self.Time}: Entry skipped; no calls at selected expiration {selected_expiry}.")
            return

        # No strike-selection rule was specified. Select the closest-to-ATM call,
        # breaking ties toward the lower strike for deterministic behavior.
        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped; SPY price unavailable for strike selection.")
            return

        selected = min(
            calls,
            key=lambda contract: (abs(contract.Strike - underlying_price), contract.Strike)
        )

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: Submitted entry for 1 SPY call {selected.Symbol}, "
            f"expiry {selected_expiry}, strike {selected.Strike}."
        )

    def HandleExitLogic(self, slice):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_order_id is not None:
            return

        expiry_date = self.held_option.ID.Date.date()
        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            self.held_option.ID.Date
        ).date()

        if self.Time.date() == previous_trading_day and self.Time.hour == 15 and self.Time.minute == 45:
            self.SubmitExit("time stop before expiration")
            return

        if self.entry_price is None or self.entry_price <= 0:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next((x for x in chain if x.Symbol == self.held_option), None)
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("50% profit target")

    def HandleExpirationProtection(self):
        if self.held_option is None:
            return

        if self.Portfolio[self.held_option].Quantity <= 0:
            return

        expiry_date = self.held_option.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_reentry_date = self.Time.date()
            if self.exit_order_id is None:
                self.Debug(f"{self.Time}: Expiration protection liquidating {self.held_option}.")
                self.SubmitExit("expiration protection")

    def HandleUnexpectedSpyEquityPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.no_reentry_date = self.Time.date()
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position ({spy_quantity}) from exercise/assignment; liquidating."
            )
            self.MarketOrder(self.spy, -spy_quantity)

    def SubmitExit(self, reason):
